// SW0 In — Parse Envelope (EACH) — preserve identity and merge
const env = $json || {};
const out = {
  ...env,
  ctx: env.ctx || {},
  characterSpecs: env.characterSpecs || env.ctx?.characterSpecs || {},
  // UPDATE: Removed hardcoded publicR2Url fallback - use backend proxy or signed URLs for external access
  publicR2Url: env.publicR2Url || null
};
return { json: out, binary: $binary || {} };

// SW0 Out — Pack Envelope (lean, but keeps the fields Return & SW1 need) — v1.1 (adds hair refs)
const j = $json || {};
const pick = (...v) => v.find(x => x !== undefined && x !== null && x !== '');

// ---------------- Normalize test flag once ----------------
const isTest = !!(j.__testMode || j.testMode || j.__meta?.__testMode || j.ctx?.__testMode || j.ctx?.testMode);

// ---------------- Derive storage paths/URLs ----------------
const assetsRoot   = j.assetsRoot || 'book-mvp-simple-adventure/order-generated-assets';
// UPDATE: Removed hardcoded publicR2Url fallback - use backend proxy or signed URLs for external access
const publicR2Url  = j.publicR2Url || null;

// Prefer existing contract, then SW0 meta from upload, then derive from hash
const baseCharacterKey =
  j.baseCharacterKey ||
  j.__meta?.storageKey ||
  (j.characterHash ? `${assetsRoot}/characters/${j.characterHash}/base-character.png` : null);

// Helpful public URL (used by SW1 HTTP fallback in tests)
// UPDATE: Only construct if publicR2Url is available (use signed URL API for external access)
const baseRefPublicUrl = (baseCharacterKey && publicR2Url) ? `${publicR2Url}/${baseCharacterKey}` : undefined;

// Hair reference fields (constructed in Restore Metadata)
const hairRefS3Key = j.hairRefS3Key || null;
const hairRefPublicUrl = j.hairRefPublicUrl || null;

// ---------------- Build lean, explicit envelope ----------------
const out = {
  // identity + context
  ctx: { ...(j.ctx || {}), characterHash: j.characterHash || j.ctx?.characterHash || null },
  amazonOrderId: j.amazonOrderId,
  characterHash: j.characterHash,
  characterPath: j.characterPath,
  assetsRoot,
  publicR2Url,

  // canonicals + prompt data
  characterSpecs: j.characterSpecs || {},
  hairStyleCanonical: pick(j.hairStyleCanonical, j.hairPromptMeta?.styleKey, j.characterSpecs?.hairStyle, 'generic'),
  clothingTypeCanonical: pick(j.clothingTypeCanonical, j.hairPromptMeta?.clothingTypeCanonical, 'tee-shorts'),
  hairPromptMeta: j.hairPromptMeta || {},
  hairPromptBlock: j.hairPromptBlock || '',

  // handy bytes/mime mirrors (so binaries can be dropped safely)
  generatedImage: j.generatedImage
    ? {
        mimeType: j.generatedImage.mimeType,
        size: j.generatedImage.size,
        modelVersion: j.generatedImage.modelVersion,
        isMock: j.generatedImage.isMock
      }
    : undefined,
  base: j.base
    ? { mime: j.base.mime, bytes: j.base.bytes, uploadKey: j.base.uploadKey }
    : undefined,

  // storage contract for downstream sub-workflows
  baseCharacterKey,          // <— SW1/SW2/SW3 need this
  baseRefPublicUrl,          // <— convenient public URL (HTTP fallback in tests)
  hairRefS3Key,              // <— SW1 needs this for Download Hair Reference
  hairRefPublicUrl,          // <— convenient public URL for hair chip

  // meta (preserve existing, plus normalized base key mirror)
  __meta: { ...(j.__meta || {}), baseUploadKey: baseCharacterKey },

  // test flag (duplicated for convenience)
  __testMode: isTest,
  testMode: isTest,
};

return { json: out, binary: {} };

// Preserve Character Specs for SW1 — restore traits after SW0 slimming
const j = $json || {};
let upstream = {};
try {
  const arr = (typeof $items === 'function') ? $items('Compute Upload Keys') : [];
  const ix = typeof $itemIndex === 'number' ? $itemIndex : 0;
  upstream = (arr[ix]?.json) || (arr[0]?.json) || {};
} catch {}

const specs = j.characterSpecs || upstream.characterSpecs || upstream.character_specs || upstream.ctx?.characterSpecs || {};

return {
  json: {
    ...j,
    characterSpecs: specs,
    ctx: {
      ...(upstream.ctx || {}),
      ...(j.ctx || {}),
      characterSpecs: j.ctx?.characterSpecs || upstream.ctx?.characterSpecs || specs
    },
    orderContext: {
      ...(upstream.orderContext || {}),
      ...(j.orderContext || {}),
      characterSpecs: j.orderContext?.characterSpecs || upstream.orderContext?.characterSpecs || specs
    },
    hairPromptBlock: j.hairPromptBlock || upstream.hairPromptBlock || ''
  },
  binary: $binary || {}
};

// Memory Cleanup After Upload1 — reattach identity, keep keys, drop heavy bits
// Mode: EACH

const j = $json || {};
const b = $binary || {};
const pick = (...v) => v.find(x => x !== undefined && x !== null && x !== '');

// If the uploader nuked context, reattach from a stable upstream node.
const UPSTREAM_NODE = 'Compute Upload Keys'; // <-- keep this name in sync
let upstream = {};
try {
  const arr = (typeof $items === 'function') ? $items(UPSTREAM_NODE) : [];
  // pick same item index if available, else first
  const ix = typeof $itemIndex === 'number' ? $itemIndex : 0;
  upstream = (arr[ix]?.json) || (arr[0]?.json) || {};
} catch { /* ignore */ }

// Prefer current JSON, but fill gaps from upstream
const root = { ...upstream, ...j };

// Pull any filename/key hints (set earlier by extractor or compute)
const fileNameHint = pick(
  b?.data?.fileName,
  root.baseGeneratedFileName,
  root.__meta?.generatedAttemptKey,
  null
);

// Identity
const fromCharactersPath = (p) => {
  if (!p || typeof p !== 'string') return null;
  const m = p.match(/characters\/([^/]+)/);
  return m ? m[1] : null;
};
const fromCharsFile = (name) => {
  if (!name || typeof name !== 'string') return null;
  const m = name.match(/characters_([A-Za-z0-9]+)_base\./);
  return m ? m[1] : null;
};

let characterHash =
  pick(root.characterHash, root.ctx?.characterHash, null)
  || fromCharactersPath(root.characterPath)
  || fromCharactersPath(root.__meta?.storageKey)
  || fromCharsFile(fileNameHint)
  || null;

const assetsRoot  = pick(root.assetsRoot, 'book-mvp-simple-adventure/order-generated-assets');
const publicR2Url = pick(root.publicR2Url, root.ctx?.publicR2Url, null);
const characterPath = pick(root.characterPath, characterHash ? `characters/${characterHash}` : null);

// Canonical storage key (even if uploader didn’t return one)
const storageKey =
  pick(root.__meta?.storageKey, null)
  || (characterPath ? `${assetsRoot}/${characterPath}/base-character.png` : null);

// Size/mime
const bytes = pick(root.base?.bytes, root.__meta?.bytes, root.uploadResult?.ContentLength, root.generatedImage?.size, null);
const mime  = pick(root.base?.mime, b?.data?.mimeType, root.generatedImage?.mimeType, 'image/png');

// Build slim JSON
const out = {
  ...(characterHash ? { characterHash } : {}),
  ...(characterPath ? { characterPath } : {}),
  assetsRoot,
  ...(publicR2Url ? { publicR2Url } : {}),
  __testMode: !!(root.__testMode || root.testMode || root.ctx?.__testMode || root.ctx?.testMode),
  __meta: {
    ...(root.__meta || {}),
    ...(storageKey ? { storageKey } : {}),
    ...(bytes ? { bytes } : {}),
    ...(fileNameHint ? { generatedAttemptKey: fileNameHint } : {})
  },
  // pass canonicals if present
  skinToneCanonical: root.skinToneCanonical,
  clothingTypeCanonical: root.clothingTypeCanonical,
  hairStyleCanonical: root.hairStyleCanonical,
  hairPromptMeta: root.hairPromptMeta,
  shortsHex: root.shortsHex,
  ...(fileNameHint ? { baseGeneratedFileName: fileNameHint } : {}),
  base: {
    ...(root.base || {}),
    ...(storageKey ? { uploadKey: storageKey } : {}),
    ...(bytes ? { bytes } : {}),
    ...(mime ? { mime } : {})
  }
};

// Drop binaries to reduce memory
return { json: out, binary: {} };

// 🧪 MOCK: Gemini Image Generation — EACH mode
// Emits a realistic Gemini response with a tiny 1x1 PNG.
// Sets flags so downstream extractor accepts tiny images in test mode.

const j = $json || {};
const itemIx = typeof $itemIndex === 'number' ? $itemIndex : 0;

// 1×1 transparent PNG (base64)
const TINY_PNG_BASE64 =
  "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg==";

// Choose response shape: 'top' (default) or 'body' to simulate HTTP wrappers
const shape = j.__mockShape === 'body' ? 'body' : 'top';

const payload = {
  candidates: [{
    content: {
      parts: [{
        inlineData: {
          mimeType: "image/png",
          data: TINY_PNG_BASE64
        }
      }]
    },
    finishReason: "STOP",
    safetyRatings: []
  }],
  usageMetadata: {
    promptTokenCount: 100,
    candidatesTokenCount: 50,
    totalTokenCount: 150
  },
  modelVersion: "gemini-2.5-flash-image-mock"
};

// Wrap under body if requested (lets you test extractor's pickRoot logic)
const mockResponse = shape === 'body' ? { body: payload } : payload;

// Mark this as a mock so the extractor relaxes size checks
mockResponse.modelVersion = mockResponse.modelVersion || "gemini-2.5-flash-image-mock";
mockResponse.__testMode = true;
mockResponse.__allowTinyImage = true;
// Optional: force a very low size gate in case flags aren’t seen
mockResponse.minImageBytes = 1;

console.log('🧪 MOCK: Returning fake image for base/pose',
  j.poseNumber ?? j.currentPoseNumber ?? '?', 'shape=', shape);

return {
  json: { ...($json || {}), ...mockResponse },
  binary: $binary || {},
  pairedItem: ($input && $input.item && $input.item.pairedItem) ? $input.item.pairedItem : { item: itemIx }
};

// Resolve Skin Tone & Base Path — ensures skinToneCanonical is present
const j = $json || {};
const cs = j.characterSpecs || {};

const normalizeKey = (s, dflt) =>
  (s && String(s).toLowerCase().trim()
      .replace(/\s+/g, '-')
      .replace(/[^a-z0-9\-]/g, '')
      .replace(/^-+|-+$/g, ''))
  || dflt;

const skinToneCanonical =
  normalizeKey(j.skinToneCanonical, null) ||
  normalizeKey(cs.skinToneCanonical, null) ||
  normalizeKey(cs.skinTone, 'skin-medium');

const clothingTypeCanonical =
  normalizeKey(j.clothingTypeCanonical, null) ||
  normalizeKey(cs.clothingType, null) ||
  normalizeKey(cs.clothingStyle, 'tee-shorts');

// keep/derive characterPath for safety
const characterHash = j.characterHash || j.ctx?.characterHash || null;
const characterPath = j.characterPath || (characterHash ? `characters/${characterHash}` : undefined);

return {
  json: {
    ...j,
    characterPath,
    skinToneCanonical,
    clothingTypeCanonical,
  },
  binary: $binary,
};

// Resolve Skin Tone & Base Path
// Mode: Run once for EACH item
// Inputs: json.characterSpecs.skinTone, .clothingType (free text from UI)
// Outputs: json.skinToneCanonical, .skinToneLabel,
//          .clothingTypeCanonical, .clothingTypeLabel,
//          .baseRefFilename, .baseRefS3Key, .baseRefPublicUrl

const j  = $json || {};
const b  = $binary || {};
const cs = j.characterSpecs || {};

// Allow overrides via JSON; otherwise use defaults
// UPDATE: Removed hardcoded PUBLIC_BASE fallback - use backend proxy or signed URLs for external access
const PUBLIC_BASE = j.publicBase ? String(j.publicBase).replace(/\/+$/,'') : null;
const ASSET_ROOT  = String(j.assetRoot  || 'book-mvp-simple-adventure/characters/bases').replace(/^\/+|\/+$/g,'');

// ------------------------- helpers -------------------------
function norm(s){
  return String(s || '')
    .toLowerCase()
    .replace(/[^a-z0-9+\-\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// ---------- Skin tone canonicalization ----------
function canonicalSkinTone(raw){
  const s = norm(raw);

  if (!s) return 'skin-medium';

  // Exact match for current frontend option IDs (light, medium, tan, medium-dark, deep)
  const FRONTEND_MAP = {
    'light': 'skin-light',
    'medium': 'skin-medium',
    'tan': 'skin-tan',
    'medium-dark': 'skin-brown-light',
    'medium dark': 'skin-brown-light',
    'deep': 'skin-brown-deep',
  };
  if (FRONTEND_MAP[s]) return FRONTEND_MAP[s];

  // accept explicit legacy keys too
  if (/(^|[^a-z])skin[-_ ]?(light|tan|medium|brown[-_ ]light|brown[-_ ]deep|dark[-_ ]aa|light[-_ ]aa)([^a-z]|$)/.test(s)) {
    if (/brown[-_ ]light|light[-_ ]aa/.test(s)) return 'skin-brown-light';
    if (/brown[-_ ]deep|dark[-_ ]aa/.test(s))  return 'skin-brown-deep';
    if (/skin[-_ ]light/.test(s))              return 'skin-light';
    if (/skin[-_ ]tan/.test(s))                return 'skin-tan';
    return 'skin-medium';
  }

  // new labels & broad synonyms
  if (/(brown).*(deep|dark)|\b(deep|dark)\b.*(brown|african|aa|black)/.test(s)) return 'skin-brown-deep';
  if (/(brown).*(light)|\blight\b.*(brown|african|aa|black)|(light)\s*(aa|african)/.test(s)) return 'skin-brown-light';
  if (/^(light|fair)(\b|$)/.test(s))                      return 'skin-light';
  if (/(tan|olive)/.test(s))                              return 'skin-tan';
  if (/(medium|mid|default|normal|average)/.test(s))      return 'skin-medium';

  // very old phrasing
  if (/(dark).*?(african|aa|black)/.test(s))              return 'skin-brown-deep';
  if (/(light).*?(african|aa|black)/.test(s))             return 'skin-brown-light';

  return 'skin-medium';
}

const skinToneCanonical = canonicalSkinTone(cs.skinTone);

// customer-facing skin labels
const CANONICAL_TO_SKIN_LABEL = {
  'skin-light':       'Light',
  'skin-tan':         'Tan',
  'skin-medium':      'Medium',
  'skin-brown-light': 'Brown — Light',
  'skin-brown-deep':  'Brown — Deep',
};
const skinToneLabel = CANONICAL_TO_SKIN_LABEL[skinToneCanonical] || CANONICAL_TO_SKIN_LABEL['skin-medium'];

// --- Clothing type canonicalization ---
const rawClothing =
  (cs.clothingType ?? cs.clothingStyle ?? j.clothingType ?? j.clothingStyle ?? '').toString();

function canonicalClothing(raw){
  const s = norm(raw);
  if (!s) return 'tee-shorts';
  if (/(^|\b)dress(es)?($|\b)/.test(s)) return 'dress';
  if (/(t[\-\s]?shirt|tee)\b/.test(s) && /\bshorts?\b/.test(s)) return 'tee-shorts';
  if (/\bshorts?\b/.test(s)) return 'tee-shorts';
  if (/tee|tshirt|t\-shirt/.test(s)) return 'tee-shorts';
  return 'tee-shorts';
}
const clothingTypeCanonical = canonicalClothing(rawClothing);

// clothing labels for audit/UI echo
const CLOTHING_LABELS = {
  'tee-shorts': 'T-shirt & shorts',
  'dress':      'Dress',
};
const clothingTypeLabel = CLOTHING_LABELS[clothingTypeCanonical] || 'T-shirt & shorts';

// ---------- Filename map (mixed extensions preserved) ----------
const FILENAME_MAP = {
  'tee-shorts': {
    'skin-brown-deep':  'base--skin-dark-aa.png',
    'skin-brown-light': 'base--skin-light-aa.png',
    'skin-light':       'base--skin-light.png',
    'skin-medium':      'base--skin-medium.jpg',     // only JPG
    'skin-tan':         'base--skin-tan.png',
  },
  'dress': {
    'skin-brown-deep':  'base--skin-dark-aa--dress.png',
    'skin-brown-light': 'base--skin-light-aa--dress.png',
    'skin-light':       'base--skin-light--dress.png',
    'skin-medium':      'base--skin-medium--dress.png',
    'skin-tan':         'base--skin-tan--dress.png',
  }
};

const clothingTable = FILENAME_MAP[clothingTypeCanonical] || FILENAME_MAP['tee-shorts'];
const baseRefFilename = clothingTable[skinToneCanonical] || clothingTable['skin-medium'];

// Build key + URL safely
const baseRefS3Key = `${ASSET_ROOT}/${baseRefFilename}`.replace(/\/{2,}/g,'/');
// UPDATE: Only construct if PUBLIC_BASE is available (use signed URL API for external access)
const baseRefPublicUrl = (PUBLIC_BASE && baseRefS3Key) ? `${PUBLIC_BASE}/${baseRefS3Key}`.replace(/\/{2,}/g,'/') : null;

// ---------- Emit (EACH mode returns a single object) ----------
const out = {
  ...j,
  skinToneCanonical,
  skinToneLabel,
  clothingTypeCanonical,
  clothingTypeLabel,
  baseRefFilename,
  baseRefS3Key,
  baseRefPublicUrl,
};

return {
  json: out,
  binary: b,
  // preserve pairing if provided upstream
  ...(($input && $input.item && $input.item.pairedItem) ? { pairedItem: $input.item.pairedItem } : {})
};

// Prepare Gemini API request for CUSTOM BASE CHARACTER (hair ref optional, skin swatch optional)
// + Clothing type & color locks (top-only color; neutral denim shorts) with HARD wardrobe override
// Mode: Run once for EACH item — returns a single object

// NOTE: Binary operations use filesystem mode for memory efficiency

const j  = { ...($json || {}) };
const cs = j.characterSpecs || {};
const b  = $binary || {};
const itemIx = (typeof $itemIndex === 'number') ? $itemIndex : 0;

// ---------- helpers ----------
function norm(s){
  return String(s || '')
    .toLowerCase()
    .replace(/[^a-z0-9#+\s-]/g,' ') // SAFE: hyphen at end
    .replace(/\s+/g,' ')
    .trim();
}
function title(s){ return String(s || '').replace(/\b\w/g, c => c.toUpperCase()); }

// ---------- clothing type canonicalization (prefer Shared Utils if available) ----------
const canonicalClothingType =
  (typeof global !== 'undefined' && global && typeof global.canonicalClothingType === 'function')
    ? global.canonicalClothingType
    : function canonicalClothingTypeLocal(raw){
        const s = norm(raw || '');
        if (/dress|sundress|gown/.test(s)) return 'dress';
        // default → tee+shorts
        return 'tee-shorts';
      };

// Map from pronouns if clothing not explicitly provided
function mapClothingFromPronouns(pronouns, explicitClothing) {
  // If clothing explicitly provided, use it
  if (explicitClothing && String(explicitClothing).trim()) {
    return String(explicitClothing).trim();
  }

  // Map from pronouns if no explicit clothing
  if (!pronouns) return null; // let canonicalClothing handle default

  const p = String(pronouns).toLowerCase().trim();

  // girl or she/her → dress
  if (p.includes('girl') || p.includes('she')) {
    return 'dress';
  }

  // boy, he/him, they/them → tee-shorts
  if (p.includes('boy') || p.includes('he') || p.includes('they')) {
    return 'tee-shorts';
  }

  return null; // let canonicalClothing handle default
}

// ---------- resolve clothing type (avoid mixing ?? and || inside call) ----------
const explicitClothing =
  cs.clothingType ??
  cs.clothingStyle ??
  j.clothingType ??
  j.clothingStyle ??
  j.clothingTypeCanonical ??
  null;

const pronounMappedClothing = mapClothingFromPronouns(cs.pronouns, explicitClothing);

// prefer pronoun-derived if present, else explicit, else fallback
const clothingRaw = pronounMappedClothing || explicitClothing || 'tee-shorts';

const clothingTypeCanonical = canonicalClothingType(clothingRaw);

// Fixed neutral denim for shorts (muted to match book palette)
const SHORTS_HEX = '#5C7393';

// ---------- favorite color (top or dress body) → HEX map ----------
const CLOTHING_COLOR_MAP = {
  'red':      '#C83f3C',
  'orange':   '#DB8A2B',
  'yellow':   '#E2C351',
  'green':    '#76A355',
  'blue':     '#4575A5',
  'pink':     '#D77A8B',
  'purple':   '#6E5A93',
  'brown':    '#6B4E38',
  'black':    '#212327'
};

// accept synonyms & raw hex
function resolveTopColor(raw){
  const s = norm(raw);
  if (!s) return { label: 'unspecified', hex: null, source: 'empty' };

  const m = s.match(/#?[0-9a-f]{6}\b/i);
  if (m){
    const hex = ('#'+m[0].replace('#','')).toUpperCase();
    return { label: 'custom-hex', hex, source: 'hex' };
  }

  const table = [
    [/sky\s*blue|navy|blue/, 'blue'],
    [/lime|forest|green/, 'green'],
    [/gold|sun|yellow/, 'yellow'],
    [/peach|orange/, 'orange'],
    [/rose|hot\s*pink|pink/, 'pink'],
    [/violet|lavender|purple/, 'purple'],
    [/chocolate|brown/, 'brown'],
    [/jet\s*black|black/, 'black'],
    [/scarlet|brick|red/, 'red'],
  ];
  for (const [re,label] of table){
    if (re.test(s)) return { label, hex: CLOTHING_COLOR_MAP[label], source: 'label' };
  }
  if (CLOTHING_COLOR_MAP[s]) return { label: s, hex: CLOTHING_COLOR_MAP[s], source: 'label-exact' };
  return { label: 'unspecified', hex: null, source: 'unknown' };
}
const topColorIn = cs.favoriteColor || j.favoriteColor || cs.topColor || '';
const topColor = resolveTopColor(topColorIn);

// ---------- 1) Resolve base reference binary ----------
const basePreferred = ['data','image','file','character','reference'];
const baseKey = basePreferred.find(k => b[k]);
if (!baseKey) {
  throw new Error('Prepare Binary (Base): No base reference image found. Expected one of binary.' + basePreferred.join('|'));
}
let baseBuf;
try { baseBuf = await this.helpers.getBinaryDataBuffer(itemIx, baseKey); }
catch { throw new Error('Prepare Binary (Base): Failed to read base buffer from key "' + baseKey + '".'); }
const base64Base = baseBuf.toString('base64');
if (!base64Base || base64Base.length < 100) throw new Error('Prepare Binary (Base): Base image base64 too short.');
const baseMime = (b[baseKey] && b[baseKey].mimeType) || 'image/png';

// ---------- 2) Optional hairstyle & skin-swatch binaries ----------
const hasHair = !!b.hair;
if (j.requireHairRef === true && !hasHair) {
  throw new Error('Prepare Binary (Base): hairstyle reference required (binary.hair) but missing.');
}

let hair64 = null, hairMime = null;
if (hasHair) {
  try {
    const hairBuf = await this.helpers.getBinaryDataBuffer(itemIx, 'hair');
    hair64 = hairBuf.toString('base64');
    hairMime = (b.hair && b.hair.mimeType) || 'image/png';
    if (!hair64 || hair64.length < 100) throw new Error('hair base64 too short');
  } catch {
    throw new Error('Prepare Binary (Base): Failed to read hairstyle reference from binary.hair.');
  }
}

// Optional skin swatch
let skin64 = null, skinMime = null;
const hasSkin = !!b.skin;
if (hasSkin) {
  try {
    const skinBuf = await this.helpers.getBinaryDataBuffer(itemIx, 'skin');
    skin64 = skinBuf.toString('base64');
    skinMime = (b.skin && b.skin.mimeType) || 'image/png';
    if (!skin64 || skin64.length < 50) throw new Error('skin swatch base64 too short');
  } catch {
    skin64 = null; skinMime = null;
  }
}

// ---------- 3) Build prompt text blocks (ordered) ----------
const styleKey = j.hairPromptMeta?.styleKey || j.hairStyleCanonical || norm(cs.hairStyle) || 'generic';
const hairColor = String(cs.hairColor || j.hairPromptMeta?.color || '').trim() || 'unspecified';

// (A) FRAMING & COMPOSITION (NEW - TOP PRIORITY)
const framingRules = [
  'FRAMING & COMPOSITION (CRITICAL):',
  '- Match IMAGE A EXACTLY for pose, scale, and framing.',
  '- Full body must be visible: head to feet, including shoes.',
  '- Character centered in frame with breathing room on all sides.',
  '- Same standing pose and proportions as IMAGE A.',
  '- Do NOT zoom in, crop legs/feet, or change character size.'
].join('\n');

// (B) CRITICAL: CLOTHING COLOR LOCK
const topColorLock =
  clothingTypeCanonical === 'dress'
    ? (topColor.hex
        ? [
            `CRITICAL — DRESS COLOR: ${topColor.hex}`,
            `The dress fabric MUST be ${topColor.hex} (${topColor.label}).`,
            'This is the REQUIRED color. Do not use any other color for the dress.',
            'Subtle book-style shading allowed within this hue only.',
            `BANNED COLORS FOR DRESS: Do not use white, gray, blue, red, green, yellow, orange, pink, purple, brown, or black UNLESS it matches ${topColor.hex}.`
          ].join('\n')
        : [
            'CRITICAL — DRESS COLOR: Use a single solid color.',
            'Keep this color consistent across all generations.',
            'Subtle book-style shading allowed.'
          ].join('\n'))
    : (topColor.hex
        ? [
            `CRITICAL — T-SHIRT COLOR: ${topColor.hex}`,
            `The t-shirt fabric MUST be ${topColor.hex} (${topColor.label}).`,
            'This is the REQUIRED color for the shirt. Do not use any other color.',
            `Shorts MUST be neutral denim ${SHORTS_HEX} (never change shorts color).`,
