// ---------- try to use Shared Utils (Init) norm() if available ----------
let norm = function normLocal(s){
  return String(s || '')
    .toLowerCase()
    .replace(/[^a-z0-9+#\s-]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
};

try {
  const utilsNode = $('Shared Utils (Init)').first();
  const utils = utilsNode?.json || {};
  const candidate = utils?.fns?.norm;

  if (typeof candidate === 'function') {
    norm = candidate;
  } else if (typeof candidate === 'string') {
    try {
      const fn = eval(`(${candidate})`);
      if (typeof fn === 'function') norm = fn;
    } catch (e) {
      console.warn("Shared norm string could not be evaluated; using local norm. Reason:", e?.message);
    }
  }
} catch {
  // ignore and keep local norm
}

// 18 canonical styles
const CANONICAL = [
  'ponytail','pigtails',
  'straight-short','straight-medium','straight-long',
  'curly-short','curly-medium','curly-long',
  'afro','pom-poms','bun','locs','side-part',
  'buzz','curly-crop','curly-tight','puffy-ponytail','small-puffy-ponytail'
];

// Canonical hair colors (matching filename convention)
const CANONICAL_COLORS = [
  'blonde','dark-brown','light-brown','medium-brown','red',
  'strawberry-blonde','auburn','black'
];

// Canonicalizer tolerant to synonyms
function canonicalStyle(styleRaw) {
  const s  = norm(styleRaw);
  if (!s) return 'generic';
  const sh = s.replace(/-/g, ' ');

  if (/buzz|buzzcut|buzz\s*cut/.test(sh)) return 'buzz';

  if (/puffy\s*ponytail|puff\s*ponytail/.test(sh) && /(large|big)/.test(sh)) return 'puffy-ponytail';
  if (/puffy\s*ponytail|puff\s*ponytail/.test(sh) && /(small|compact)/.test(sh)) return 'small-puffy-ponytail';
  if (/puffy\s*ponytail|puff\s*ponytail/.test(sh)) return 'puffy-ponytail';

  if (/curly\s*crop|crop\s*curly/.test(sh)) return 'curly-crop';
  if (/curly\s*tight|tight\s*curly|tightly?\s*coiled/.test(sh)) return 'curly-tight';

  if (/(^|\s)pom\s*poms?($|\s)|space\s*buns?|puffs?/.test(sh)) return 'pom-poms';
  if (/pig[-\s]*tails?/.test(s)) return 'pigtails';
  if (/side\s*part/.test(sh)) return 'side-part';
  if (/(^|\s)bun($|\s)/.test(sh)) return 'bun';
  if (/(locs|dreadlocks|dreads)/.test(sh)) return 'locs';
  if (/afro/.test(sh)) return 'afro';
  if (/ponytail|pony\s*tail/.test(sh)) return 'ponytail';

  if (/straight/.test(sh) && /(short|above\s*chin|chin)/.test(sh)) return 'straight-short';
  if (/straight/.test(sh) && /(medium|shoulder|to\s*shoulders?)/.test(sh)) return 'straight-medium';
  if (/straight/.test(sh) && /(long|below\s*shoulders?)/.test(sh)) return 'straight-long';
  if (/straight/.test(sh)) return 'straight-medium';

  if (/(curly|curls)/.test(sh) && /(short|halo)/.test(sh)) return 'curly-short';
  if (/(curly|curls)/.test(sh) && /(medium|shoulder)/.test(sh)) return 'curly-medium';
  if (/(curly|curls)/.test(sh) && /(long|below\s*shoulders?)/.test(sh)) return 'curly-long';
  if (/(curly|curls)/.test(sh)) return 'curly-medium';

  return 'generic';
}

// Canonicalize hair color
function canonicalColor(colorRaw) {
  const c = norm(colorRaw).replace(/\s+/g, '-');
  if (!c) return 'medium-brown';

  if (CANONICAL_COLORS.includes(c)) return c;

  if (/^(dark[_\s-]?brown|darkbrown)$/.test(c)) return 'dark-brown';
  if (/^(light[_\s-]?brown|lightbrown)$/.test(c)) return 'light-brown';
  if (/^(medium[_\s-]?brown|mediumbrown|brown)$/.test(c)) return 'medium-brown';
  if (/^(strawberry[_\s-]?blonde|strawberryblonde)$/.test(c)) return 'strawberry-blonde';
  if (/^blonde?$/.test(c)) return 'blonde';
  if (/^(ginger|orange)$/.test(c)) return 'red';
  if (/^auburn$/.test(c)) return 'auburn';
  if (/^black$/.test(c)) return 'black';

  return 'medium-brown';
}

const styleKeyRaw =
