// Extract BASE CHARACTER image from Gemini response — EACH mode
// Accepts tiny images in mock/test mode; enforces min size in production.
// *** IMPORTANT: merge upstream context from BEFORE the HTTP call ***

const apiJson = $json || {};         // this is the raw HTTP response
const b = $binary || {};
const itemIx = (typeof $itemIndex === 'number') ? $itemIndex : 0;

// --- fetch upstream context (pre-HTTP) so we don’t lose fields like hairPromptMeta ---
function safeItems(name, runIx) {
  try { return $items(name, 0, runIx) || $items(name) || []; } catch { return []; }
}
const runIx = (typeof $runIndex === 'number') ? $runIndex : 0;
