  const now  = safeItems(n, runIx);
  const seed = safeItems(n, 0);
  upstream = (now[itemIx]?.json) || (seed[itemIx]?.json) || now[0]?.json || seed[0]?.json || upstream;
  if (upstream && Object.keys(upstream).length) break;
}
upstream = upstream || {};

// --- tiny util ---
const pick = (...v) => v.find(x => x !== undefined && x !== null && x !== '');

// ---------- helpers for inline image ----------
function pickRoot(r){
  if (r?.body?.candidates) return r.body;
  if (r?.response?.candidates) return r.response;
  if (r?.data?.candidates) return r.data;
  return r;
}

function firstInlineFromParts(parts){
  if (!Array.isArray(parts)) return null;
  for (const p of parts){
    const id = p?.inlineData?.data || p?.inline_data?.data;
    if (id) {
      return {
        b64: String(id),
        mime: p?.inlineData?.mimeType || p?.inline_data?.mime_type || 'image/png',
        path: 'content.parts.inlineData'
      };
    }
  }
  return null;
}

function findInlineImage(r){
  const cand = r?.candidates?.[0];
  if (cand?.content?.parts){
    const got = firstInlineFromParts(cand.content.parts);
    if (got) return got;
  }
  if (Array.isArray(cand?.content) && cand.content[0]?.parts){
    const got = firstInlineFromParts(cand.content[0].parts);
    if (got) return got;
  }
  // Deep scan as last resort
  const stack = [r];
  while (stack.length) {
    const cur = stack.pop();
    if (!cur || typeof cur !== 'object') continue;
    const d = cur?.inlineData?.data || cur?.inline_data?.data;
    if (d) {
      return {
        b64: String(d),
        mime: cur?.inlineData?.mimeType || cur?.inline_data?.mime_type || 'image/png',
        path: '...inlineData/inline_data (fallback)'
      };
    }
    for (const k of Object.keys(cur)) {
      const v = cur[k];
      if (v && typeof v === 'object') stack.push(v);
    }
  }
  return null;
}

// 32-bit FNV-1a (fallback hash)
function fnv1aHex(buf){
  let h = 0x811c9dc5 >>> 0;
  for (let i = 0; i < buf.length; i++){
    h ^= buf[i];
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return ('00000000' + h.toString(16)).slice(-8);
}

