      '- Use ONLY for part location, silhouette outline, maximum length, and placement.',
      '- Do NOT copy face, skin tone, eyes, clothes, or colors from IMAGE B — hair shape only.'
    ].join('\n')
  : '';

/* ---------------- Outfit/Clothing Lock ---------------- */
const outfitLock =
  clothingTypeCanonical === 'dress'
    ? [
        'OUTFIT / CLOTHING LOCK:',
        '- Outfit MUST remain a DRESS (single-piece).',
        '- Do NOT replace with a T-shirt and shorts, pants, or layered outfits.',
        '- Keep the same dress silhouette as IMAGE A (short sleeves, A-line body); no waist seam or shorts hem visible.'
      ].join('\n')
    : [
        'OUTFIT / CLOTHING LOCK:',
        '- Outfit MUST remain a short-sleeve T-SHIRT and SHORTS.',
        '- Do NOT replace with a dress, skirt, pants, or layered outfits.',
        '- Keep shorts length and T-shirt silhouette consistent with IMAGE A.'
      ].join('\n');

/* ---------------- Hair-color lock ---------------- */
const hairColorLock = colorCanon.hex
  ? `HAIR COLOR LOCK: Use ${colorCanon.hex} consistently across ALL generated images. Do not recolor, lighten/darken, or shift undertone.`
  : 'HAIR COLOR LOCK: Keep the selected hair color consistent across ALL generated images. Do not recolor or shift undertone.';

/* ---------------- Build final block ---------------- */
const allowScallop = ['curly-short','curly-medium','curly-long','afro','pom-poms','curly-crop','curly-tight','puffy-ponytail','small-puffy-ponytail'].includes(styleKey);
const baseLines = PROMPT_MAP[styleKey] || PROMPT_MAP['generic'];

// Recommended order: outfit lock → color lock → style → image usage → hygiene
const hairPromptBlock = [
  outfitLock,
  hairColorLock,
  ...baseLines,
  hairRefUsageBlock || null,
  ...hygieneLines(allowScallop)
].filter(Boolean).join('\n');

/* ---------------- Preserve & normalize binary for downstream ---------------- */
const binaryIn = b;
const binaryKeys = Object.keys(binaryIn);
const preferredBinaryKeys = ['data','image','file','character','reference','hair'];
const hasPreferred = preferredBinaryKeys.some(k => binaryIn[k]);
let binaryOut = binaryKeys.length ? { ...binaryIn } : undefined;
if (binaryOut && !hasPreferred && binaryKeys.length) {
  const firstKey = binaryKeys[0];
  binaryOut.image = binaryOut[firstKey];
}

/* ---------------- Emit (EACH mode => single object) ---------------- */
const out = {
  ...j,
  // surface canonicals for downstream and auditing
  hairStyleCanonical: CANONICAL_STYLES.includes(styleKey) ? styleKey : 'generic',
  clothingTypeCanonical,
  hairPromptBlock,
  hairPromptMeta: {
    ...(j.hairPromptMeta || {}),
    styleKey: CANONICAL_STYLES.includes(styleKey) ? styleKey : 'generic',
    colorLabel: colorCanon.id,
    colorHex: colorCanon.hex,
    hairColorLock,
    clothingTypeCanonical,
    promptVersion: 'v1.5-haircolor-lock+outfit-lock',
    allowedKeys: CANONICAL_STYLES,
    source: 'dynamic-hairstyle-prompt-map',
    _debug: {
      receivedHairStyle: styleIn,
      receivedHairColor: colorInput,
      hairColorSource: colorCanon.source,
      normalizedStyle: norm(styleIn),
      matchedStyleKey: CANONICAL_STYLES.includes(styleKey) ? styleKey : 'generic',
      clothingTypeRaw: clothingRaw,
      hasHairRef
    }
  }
};

return {
  json: out,
  binary: binaryOut ?? b
  // (No pairedItem needed in EACH; n8n handles mapping automatically)
};
